import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Sidebar from "../../components/Sidebar";
import "../../styles/Lesson.css";

export default function Biology() {
  const [sub, setSub] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lessons, setLessons] = useState([]);
  const [introWatched, setIntroWatched] = useState(false);

  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user")) || null;

  // Check if intro was already watched
  useEffect(() => {
    const introKey = `intro_watched_${sub?.id}_user_${user?.id || "guest"}`;
    const watched = localStorage.getItem(introKey);
    if (watched) {
      setIntroWatched(true);
    }
  }, [sub, user]);

  useEffect(() => {
    async function load() {
      try {
        const res = await fetch("http://localhost:8080/resources");
        const data = await res.json();
        const found = (data.subsciences || []).find((s) => /bio/i.test(s.name) || s.code === "biology");
        setSub(found || null);

        if (found) {
          // try to fetch lessons for this subscience for the current user
          try {
            const lid = user ? user.id : "";
            const lres = await fetch(`http://localhost:8080/subsciences/${found.id}/lessons/${lid}`);
            const ldata = await lres.json();
            const fetched = ldata.lessons || [];

            // detect first visit for this user+subscience using localStorage
            const visitedKey = `visited_sub_${found.id}_user_${user?.id || "guest"}`;
            const firstVisit = !localStorage.getItem(visitedKey);

            // ensure there are 10 lessons (pad if backend doesn't provide)
            const pad = [];
            for (let i = 1; i <= 10; i++) {
              const ex = fetched.find((f) => f.lesson_number === i);
              let lessonStatus = ex?.status || "locked";

              // Lesson 1 unlocks when intro is watched
              if (i === 1) {
                lessonStatus = introWatched ? "unlocked" : "locked";
              }
              // Unlock next lesson if previous one is completed
              else if (i > 1) {
                const prevLesson = pad[i - 2];
                if (prevLesson?.status === "completed") {
                  lessonStatus = "unlocked";
                } else {
                  lessonStatus = "locked";
                }
              }

              pad.push(ex ? { ...ex, status: lessonStatus } : { id: `local-${i}`, lesson_number: i, title: `Lesson ${i}`, status: lessonStatus });
            }

            // mark visited so next time we respect backend progress
            if (firstVisit) localStorage.setItem(visitedKey, Date.now().toString());

            setLessons(pad);
          } catch (err) {
            // fallback: create 10 lessons with lesson 1 locked initially
            const pad = [];
            for (let i = 1; i <= 10; i++) {
              const status = i === 1 ? (introWatched ? "unlocked" : "locked") : "locked";
              pad.push({ id: `local-${i}`, lesson_number: i, title: `Lesson ${i}`, status });
            }
            setLessons(pad);
          }
        } else {
          // no resources/subscience found: lesson 1 still respects introWatched, others are schedule_locked
          const pad = [];
          for (let i = 1; i <= 10; i++) {
            let status = "schedule_locked";
            if (i === 1) {
              status = introWatched ? "unlocked" : "locked";
            }
            pad.push({ id: `local-${i}`, lesson_number: i, title: `Lesson ${i}`, status });
          }
          setLessons(pad);
        }
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    }
    load();
  }, [user, introWatched]);

  function markIntroWatched() {
    // Mark intro as watched in localStorage
    const introKey = `intro_watched_${sub?.id || "none"}_user_${user?.id || "guest"}`;
    localStorage.setItem(introKey, Date.now().toString());

    // Set intro watched state (will trigger useEffect with introWatched dependency to reload lessons)
    setIntroWatched(true);
  }

  function markLessonCompleted(lessonId) {
    setLessons((prev) => {
      const updated = prev.map((ls) => {
        if (ls.id === lessonId) {
          return { ...ls, status: "completed" };
        }
        return ls;
      });

      // Unlock next lesson if the current one is completed
      const completedLessonIndex = updated.findIndex((l) => l.id === lessonId);
      if (completedLessonIndex >= 0 && completedLessonIndex < updated.length - 1) {
        const nextLesson = updated[completedLessonIndex + 1];
        if (nextLesson.status === "locked") {
          updated[completedLessonIndex + 1] = { ...nextLesson, status: "unlocked" };
        }
      }

      return updated;
    });

    // Persist to backend if not a local lesson
    if (!String(lessonId).startsWith("local-")) {
      fetch(`http://localhost:8080/lesson_progress/complete`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: user?.id, lesson_id: lessonId }),
      }).catch((e) => console.warn("Could not persist completion:", e));
    }
  }

  function viewLesson(lesson) {
    navigate(`/lesson/${lesson.id}`, { state: { lesson, subId: sub?.id, onComplete: markLessonCompleted } });
  }

  return (
    <div className="dashboard-page">
      <Sidebar />
      <main className="dashboard-main">
        <header className="dashboard-header">
          <div>
            <h1>Biology</h1>
            <p className="dashboard-subtitle">Discover living systems, cells, genetics and ecology.</p>
          </div>
        </header>

        {loading ? (
          <p className="dashboard-loading">Loading...</p>
        ) : (
          <div style={{ display: "flex", gap: "2rem", alignItems: "flex-start" }}>
            {/* Intro video - Left side */}
            <section style={{ 
              flex: "0 0 45%",
              background: "linear-gradient(135deg, #fbfdff, #f8f7ff)",
              border: "1px solid #e5e7eb",
              borderRadius: "16px",
              padding: "2rem",
              boxShadow: "0 4px 16px rgba(0, 0, 0, 0.05)",
              height: "fit-content",
              position: "sticky",
              top: "2rem"
            }}>
              <h2 style={{ fontSize: "1.5rem", marginBottom: "1rem", margin: "0 0 1rem 0", color: "#1f2937" }}>Intro to Biology</h2>
              <div style={{ position: "relative", paddingBottom: "56.25%", height: 0, marginBottom: "1rem", borderRadius: "12px", overflow: "hidden" }}>
                <iframe
                  title="Biology Intro"
                  src="https://www.youtube.com/embed/PWGBqskV1UQ?rel=0"
                  style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%" }}
                  frameBorder="0"
                  allowFullScreen
                />
              </div>
              {!introWatched && (
                <button 
                  onClick={markIntroWatched}
                  style={{
                    width: "100%",
                    background: "linear-gradient(135deg, #6366f1, #8b5cf6)",
                    color: "white",
                    border: "none",
                    padding: "0.75rem 1.5rem",
                    borderRadius: "8px",
                    fontSize: "1rem",
                    fontWeight: "600",
                    cursor: "pointer",
                    transition: "all 300ms ease",
                    boxShadow: "0 4px 12px rgba(99, 102, 241, 0.3)"
                  }}
                >
                  I've finished watching
                </button>
              )}
              {introWatched && (
                <div style={{
                  padding: "0.75rem 1rem",
                  background: "linear-gradient(135deg, rgba(16, 185, 129, 0.12), rgba(0, 255, 136, 0.12))",
                  color: "#059669",
                  borderRadius: "8px",
                  fontWeight: "600",
                  textAlign: "center"
                }}>
                  ✓ Intro Completed
                </div>
              )}
            </section>

            {/* Lessons - Right side */}
            {introWatched && (
              <section style={{ flex: "1" }}>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: "1rem", marginBottom: "1.5rem" }}>
                  <h2 style={{ fontSize: "1.5rem", margin: 0, color: "#1f2937" }}>Lessons</h2>
                  <p style={{ fontSize: "0.875rem", color: "#9ca3af", margin: 0 }}>
                    {lessons.filter(l => l.status === "completed").length} / {lessons.length} completed
                  </p>
                </div>
                <ul className="lessons-grid">
                  {lessons.map((lesson) => (
                    <li key={lesson.id} className={`lesson-card ${lesson.status}`}>
                      <div className="lesson-card-number">{lesson.lesson_number}</div>
                      <div className="lesson-card-content">
                        <h3>{lesson.title}</h3>
                        <p className="lesson-status">
                          {lesson.status === "completed" && "✓ Completed"}
                          {lesson.status === "unlocked" && "Ready to start"}
                          {lesson.status === "locked" && "Locked"}
                          {lesson.status === "schedule_locked" && "Select resources"}
                        </p>
                      </div>
                      <button
                        className="lesson-card-btn"
                        disabled={lesson.status === "locked" || lesson.status === "schedule_locked"}
                        onClick={() => viewLesson(lesson)}
                      >
                        View →
                      </button>
                    </li>
                  ))}
                </ul>
              </section>
            )}
          </div>
        )}
      </main>
    </div>
  );
}
